#!/usr/bin/env python3
"""compute_gamma_unrelaxed_baseline.py -- gamma before relaxation (gamma_pre) of the structures generated by the baseline (standard mattergen-generate).

Difference from the proposed-model version (compute_gamma_pre_proposed.py):
  * The input is chunkNN/{chunk_meta.json, generated_crystals.extxyz} (neither generation_metrics.json nor the expansion of cif/ is used).
  * The lattice of the baseline is free (axes are exchanged by Niggli reduction), so for each structure the axes are canonicalized in descending order of length (a function copy of the logic of
    measure_chunk_equivalence.sh:118-165 of the earlier baseline) before gamma is computed. Area = |L2 x L3| after canonicalization.
  * The formula of gamma, mu_Al and the conversion constant use single_point_gamma of v2 (compute_gamma_unrelaxed.py) as it is (not copied).
    Only V2.build_calc / V2.single_point_gamma / V2.OUT_FIELDS are used.

Output CSV: columns = V2.OUT_FIELDS + [non_al_count, angle_max_dev_deg, perm, len_L1]. 1 structure = 1 row (error rows are also kept).
  - Angle check: angle_ok when all 3 angles satisfy |theta-90| <= angle_tol. Otherwise error="angle_fail" and gamma is empty (not canonicalized).
  - non_al_count = (numbers != 13).sum(). gamma is computed (not excluded; exclusion is the user's ruling).
  - --dry-run: does not call MACE, leaves energy/gamma empty and computes up to area_A2 (the error of a normal row is DRY_RUN_SKIPPED, as in v2).

Usage (do not start a plain python on the login node: use the venv python on <GPU_LOGIN_NODE> or the evaluation environment on a compute node):
  ${GEN_PY} compute_gamma_unrelaxed_baseline.py --gen-root <dir> --expect-chunks 50 \
      --expect-per-chunk 10 --arm-label baseline_dedup_w2 --out <csv> [--dry-run] [--angle-tol-deg 1.0] [--allow-overwrite]
  A real calculation (without --dry-run) requires a GPU.
"""
from __future__ import annotations
import paths as _gbrel  # gb_eval/paths.py (reads GBREL_* environment variables; no defaults)

import argparse
import csv
import importlib.util
import json
import sys
import time
from pathlib import Path

import numpy as np

# ---- loading of v2 (a verbatim copy of _load_v2 and the V2_PATH candidates of compute_gamma_pre_proposed.py:35-60) ----
_V2_CANDIDATES = [
    Path(_gbrel.CODE + '/gb_eval/experiments/dx_gamma_unrelaxed/scripts/compute_gamma_unrelaxed.py'),
    Path(_gbrel.CODE + '/gb_eval/experiments/dx_gamma_unrelaxed/scripts/compute_gamma_unrelaxed.py'),
    Path(_gbrel.CODE + '/gb_eval/experiments/dx_gamma_unrelaxed/scripts/compute_gamma_unrelaxed.py'),
]
V2_PATH = next((p for p in _V2_CANDIDATES if p.is_file()), _V2_CANDIDATES[0])


def _load_v2():
    if not V2_PATH.is_file():
        raise RuntimeError(f"v2 not found: {V2_PATH}")
    spec = importlib.util.spec_from_file_location("compute_gamma_unrelaxed", str(V2_PATH))
    mod = importlib.util.module_from_spec(spec)
    sys.modules["compute_gamma_unrelaxed"] = mod
    spec.loader.exec_module(mod)
    return mod


V2 = _load_v2()
OUT_FIELDS = list(V2.OUT_FIELDS) + ["non_al_count", "angle_max_dev_deg", "perm", "len_L1"]
REQUIRED_META_KEYS = ["gamma_target_J_m2", "seed", "checkpoint_path", "num_samples_requested"]
AL_Z = 13

DET_REL_TOL = 1e-9   # relative tolerance for conservation of |det| (measure_chunk_equivalence.sh:153)
L1_REL_TOL = 1e-6    # relative tolerance of L2[0,0] == L1 (same:161)


class BaselineError(RuntimeError):
    """FATAL equivalent (main converts it to exit 2)."""


class CanonError(BaselineError):
    """The cross-check of the canonicalization failed (no silent fallback)."""


# ---------------------------------------------------------------------------
# angle
# ---------------------------------------------------------------------------
def angle_dev_deg(atoms) -> float:
    """Maximum deviation [deg] of the 3 cell angles from 90 deg."""
    from ase.geometry import cell_to_cellpar

    cellpar = cell_to_cellpar(np.asarray(atoms.cell.array, dtype=np.float64))
    return float(max(abs(float(a) - 90.0) for a in cellpar[3:6]))


# ---------------------------------------------------------------------------
# canonicalization (a function copy of measure_chunk_equivalence.sh:118-165). The computation and the cross-check are separated so that an input for which the cross-check fails can be made from a validation case.
# ---------------------------------------------------------------------------
def canonical_axes(atoms, *, do_flip: bool = True) -> dict:
    """Sorts the axes in descending order of length (the same permutation for rows and columns). If det<0 the third axis is reversed (do_flip=False is a modification "do not reverse" for validation).
    Returns: perm, L2, s2, axis_flipped, lengths, det_orig, det_canon. The cross-check is verify_canonical."""
    L = np.asarray(atoms.cell.array, dtype=np.float64)
    lengths = np.linalg.norm(L, axis=1)
    order = np.argsort(-lengths)  # all 6 permutations are covered
    perm = [int(x) for x in order]
    s = atoms.get_scaled_positions(wrap=True).astype(np.float64)
    L2 = L[perm, :][:, perm]  # rotate both rows and columns with the same permutation (rows alone collapse to n_layers=1)
    s2 = s[:, perm]
    axis_flipped = False
    if do_flip and np.linalg.det(L2) < 0:
        L2 = L2.copy()
        L2[2, :] = -L2[2, :]
        s2 = s2.copy()
        s2[:, 2] = (-s2[:, 2]) % 1.0
        axis_flipped = True
    return {
        "perm": perm, "L2": L2, "s2": s2, "axis_flipped": axis_flipped, "lengths": lengths,
        "det_orig": float(np.linalg.det(L)), "det_canon": float(np.linalg.det(L2)),
    }


def verify_canonical(atoms, canon: dict) -> None:
    """Cross-check (CanonError if violated). The same 4 checks as measure_chunk_equivalence.sh:149-165."""
    perm, L2, s2 = canon["perm"], canon["L2"], canon["s2"]
    det_orig, det_canon = canon["det_orig"], canon["det_canon"]
    if len(atoms) != s2.shape[0]:
        raise CanonError(f"atom count mismatch after canonicalization (orig={len(atoms)}, canon={s2.shape[0]})")
    if abs(abs(det_canon) - abs(det_orig)) > DET_REL_TOL * abs(det_orig):
        raise CanonError(f"|det| not preserved within {DET_REL_TOL:g} rel: det_orig={det_orig} det_canon={det_canon}")
    if det_canon <= 0:
        raise CanonError(f"det_canon={det_canon} is not > 0")
    len_L1 = float(canon["lengths"][perm[0]])
    if abs(L2[0, 0] - len_L1) > L1_REL_TOL * abs(len_L1):
        raise CanonError(f"canonicalized lat[0,0]={L2[0, 0]} != L1={len_L1} (rel tol {L1_REL_TOL:g}; angle_ok structure should satisfy this)")


def canonicalize(atoms):
    """atoms -> (canon_atoms, info). The species and the atom order are not changed (copy + only the cell and positions are reassigned)."""
    canon = canonical_axes(atoms)
    verify_canonical(atoms, canon)
    new_atoms = atoms.copy()
    new_atoms.set_cell(canon["L2"])
    new_atoms.set_scaled_positions(canon["s2"])
    info = {"perm": canon["perm"], "len_L1": float(canon["lengths"][canon["perm"][0]]),
            "axis_flipped": canon["axis_flipped"], "det_canon": canon["det_canon"]}
    return new_atoms, info


# ---------------------------------------------------------------------------
# processing of one structure (also called from the validation)
# ---------------------------------------------------------------------------
def process_structure(atoms, calc, *, angle_tol_deg: float, dry_run: bool) -> dict:
    """Returns a dict with only the columns derived from the structure among OUT_FIELDS. CanonError is not swallowed and goes up (FATAL)."""
    dev = angle_dev_deg(atoms)
    row = {
        "gamma_unrelaxed": "", "natoms": len(atoms), "area_A2": "", "energy_eV": "", "error": "",
        "non_al_count": int((np.asarray(atoms.numbers) != AL_Z).sum()),
        "angle_max_dev_deg": dev, "perm": "", "len_L1": "",
    }
    if not (dev <= angle_tol_deg):
        row["error"] = "angle_fail"
        return row
    canon_atoms, info = canonicalize(atoms)
    row["perm"] = json.dumps(info["perm"])
    row["len_L1"] = info["len_L1"]
    if dry_run:
        row["area_A2"] = V2.in_plane_area_bc(canon_atoms)   # area = |L2 x L3| (after canonicalization; in_plane_area_bc of v2 is b x c)
        row["error"] = "DRY_RUN_SKIPPED"
        return row
    try:
        out = V2.single_point_gamma(canon_atoms, calc)
        row["gamma_unrelaxed"] = out["gamma_unrelaxed"]
        row["natoms"] = out["natoms"]
        row["area_A2"] = out["area_A2"]
        row["energy_eV"] = out["energy_eV"]
    except Exception as e:  # noqa: BLE001  failures on the MACE side are kept in the row (handled as in v2)
        row["error"] = f"{type(e).__name__}: {e}"
        row["area_A2"] = V2.in_plane_area_bc(canon_atoms)
    return row


# ---------------------------------------------------------------------------
# scan of the chunks
# ---------------------------------------------------------------------------
def load_chunk(chunk_dir: Path, expect_per_chunk: int):
    from ase.io import read as ase_read

    meta_path = chunk_dir / "chunk_meta.json"
    if not meta_path.is_file():
        raise BaselineError(f"{meta_path}: chunk_meta.json missing")
    meta = json.loads(meta_path.read_text())
    for k in REQUIRED_META_KEYS:
        if k not in meta:
            raise BaselineError(f"{meta_path}: required key {k!r} missing (C1: no silent fallback)")
    xyz = chunk_dir / "generated_crystals.extxyz"
    if not xyz.is_file():
        raise BaselineError(f"{xyz}: not found")
    atoms_list = ase_read(str(xyz), index=":")
    if len(atoms_list) != expect_per_chunk:
        raise BaselineError(f"{xyz}: {len(atoms_list)} structures != expect-per-chunk {expect_per_chunk}")
    if int(meta["num_samples_requested"]) != len(atoms_list):
        raise BaselineError(f"{meta_path}: num_samples_requested={meta['num_samples_requested']} != {len(atoms_list)} structures in extxyz")
    return meta, atoms_list


def run(args) -> list[dict]:
    gen_root = Path(args.gen_root)
    out_csv = Path(args.out)
    if out_csv.exists() and not args.allow_overwrite:
        raise BaselineError(f"--out {out_csv} already exists (no overwrite; pass --allow-overwrite to permit)")
    if not gen_root.is_dir():
        raise BaselineError(f"--gen-root not found: {gen_root}")

    calc = None
    if not args.dry_run:
        print("[GUARD] vram_precheck ...", flush=True)
        free_gib = V2.RG.vram_precheck(min_free_gib=8.0)
        print(f"[GUARD] VRAM free={free_gib:.1f} GiB", flush=True)
        calc, model_path = V2.build_calc()
        print(f"MACE model: {model_path}", flush=True)
    else:
        print("--dry-run: skipping MACE model load and single-point evaluation", flush=True)

    t0 = time.time()
    out_rows: list[dict] = []
    n_ok = n_err = 0
    for ci in range(args.expect_chunks):
        cdir = gen_root / f"chunk{ci:02d}"
        if not cdir.is_dir():
            raise BaselineError(f"chunk dir missing: {cdir}")
        meta, atoms_list = load_chunk(cdir, args.expect_per_chunk)
        for i, atoms in enumerate(atoms_list):
            res = process_structure(atoms, calc, angle_tol_deg=args.angle_tol_deg, dry_run=args.dry_run)
            row = {k: "" for k in OUT_FIELDS}
            row.update({
                "arm": args.arm_label, "gamma_target": meta["gamma_target_J_m2"], "seed": meta["seed"],
                "struct_idx": i, "chunk_dir": str(cdir), "cif_index": i, "checkpoint_path": meta["checkpoint_path"],
            })
            row.update(res)
            out_rows.append(row)
            if res["error"] and res["error"] != "DRY_RUN_SKIPPED":
                n_err += 1
                print(f"[ERROR] {cdir} struct_idx={i}: {res['error']}", flush=True)
            else:
                n_ok += 1
        print(f"[progress] chunk{ci:02d} done rows={len(out_rows)} n_ok={n_ok} n_err={n_err} elapsed={time.time() - t0:.1f}s", flush=True)

    expect_rows = args.expect_chunks * args.expect_per_chunk
    if len(out_rows) != expect_rows:
        raise BaselineError(f"row count {len(out_rows)} != expect-chunks x expect-per-chunk = {expect_rows}")
    out_csv.parent.mkdir(parents=True, exist_ok=True)
    with open(out_csv, "w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=OUT_FIELDS)
        w.writeheader()
        w.writerows(out_rows)
    n_angle_fail = sum(1 for r in out_rows if r["error"] == "angle_fail")
    n_non_al = sum(1 for r in out_rows if int(r["non_al_count"]) > 0)
    mode = "DRY_RUN" if args.dry_run else "MAIN"
    print(f"{mode}_DONE arm={args.arm_label} n_rows={len(out_rows)} n_err_or_fail={n_err} n_angle_fail={n_angle_fail} "
          f"n_non_al={n_non_al} elapsed={time.time() - t0:.1f}s -> {out_csv}", flush=True)
    return out_rows


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--gen-root", required=True, help="directory that directly contains chunkNN/ (chunk_meta.json + generated_crystals.extxyz)")
    ap.add_argument("--expect-chunks", required=True, type=int)
    ap.add_argument("--expect-per-chunk", required=True, type=int)
    ap.add_argument("--arm-label", required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--angle-tol-deg", type=float, default=1.0)
    ap.add_argument("--allow-overwrite", action="store_true")
    ap.add_argument("--dry-run", action="store_true", help="does not call MACE, leaves energy/gamma empty and computes up to area_A2 (no GPU needed)")
    args = ap.parse_args()
    try:
        run(args)
    except BaselineError as e:
        print(f"FATAL: {e}", file=sys.stderr)
        sys.exit(2)


if __name__ == "__main__":
    main()
